package com.gathin.tvhome;

import android.app.Activity;
import android.os.Bundle;
import android.content.pm.*;
import android.graphics.*;
import android.graphics.drawable.*;
import android.view.*;
import android.widget.*;
import androidx.annotation.NonNull;
import androidx.recyclerview.widget.*;
import java.util.*;
import java.util.concurrent.*;

/** Draft selections for three categories. A single save commits them together. */
public final class CategorySettingsActivity extends Activity {
    private static final ExecutorService LOADER=Executors.newSingleThreadExecutor();
    private final List<App> apps=new ArrayList<>();
    private final Map<String,Set<String>> draft=new HashMap<>();
    private final Set<String> dirty=new HashSet<>();
    private final Map<String,List<String>> orderDraft=new HashMap<>();
    private final Set<String> orderDirty=new HashSet<>();
    private final Map<String,TextView> tabs=new HashMap<>();
    private RecyclerView grid;
    private TextView count;
    private String category="movies";
    private boolean ready;
    private String focusPackage="";
    private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private String tr(String he,String ru){return CategoryDock.text(this,he,ru);}
    private String label(String key){return key.equals("tv")?tr("טלוויזיה","Телевидение"):key.equals("movies")?tr("סרטים וסדרות","Фильмы и сериалы"):tr("אפליקציות","Приложения");}
    private TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(Color.WHITE);return t;}
    private GradientDrawable surface(int color,int stroke){GradientDrawable d=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{color,color});d.setCornerRadius(dp(12));if(stroke!=0)d.setStroke(dp(1),stroke);return d;}
    private TextView button(String label,Runnable action,boolean primary){TextView b=text(label,16);b.setTypeface(Typeface.DEFAULT,Typeface.BOLD);b.setGravity(Gravity.CENTER);b.setFocusable(true);b.setClickable(true);b.setBackground(surface(primary?0xFF073F95:0xFF252525,0x66777777));b.setOnClickListener(v->{if(ready)action.run();});b.setOnFocusChangeListener((v,has)->{v.setBackground(surface(has?0xFF123C70:primary?0xFF073F95:0xFF252525,has?Color.WHITE:0x66777777));v.animate().scaleX(has?1.025f:1).scaleY(has?1.025f:1).setDuration(120).start();});return b;}
    @Override public void onCreate(Bundle saved){super.onCreate(saved);String requested=getIntent().getStringExtra("category");if(requested!=null)category=requested;
        LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(56),dp(26),dp(56),dp(18));root.setBackground(new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xFF3A210D,0xFF100A05,Color.BLACK}));root.addView(CategoryHeader.create(this,root));
        LinearLayout heading=new LinearLayout(this);heading.setGravity(Gravity.CENTER_VERTICAL);TextView title=text(tr("הגדרות תצוגה","Настройки отображения"),34);title.setTypeface(Typeface.DEFAULT,Typeface.BOLD);title.setGravity(Gravity.RIGHT);heading.addView(title,new LinearLayout.LayoutParams(-1,dp(54)));root.addView(heading);
        TextView hint=text(tr("בחרו אילו אפליקציות יוצגו בכל קטגוריה","Выберите приложения для каждой категории"),15);hint.setTextColor(0xFFBBBBBB);hint.setGravity(Gravity.RIGHT);root.addView(hint,new LinearLayout.LayoutParams(-1,dp(29)));
        LinearLayout tabRow=new LinearLayout(this);tabRow.setPadding(0,dp(3),0,dp(7));for(String key:new String[]{"tv","movies","apps"}){TextView tab=button(label(key),()->switchCategory(key),false);tabs.put(key,tab);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(180),dp(43));p.rightMargin=dp(10);tabRow.addView(tab,p);}TextView reorder=button(tr("↕  שינוי סדר","↕  Порядок"),this::openOrder,false);LinearLayout.LayoutParams reorderParams=new LinearLayout.LayoutParams(dp(130),dp(43));reorderParams.rightMargin=dp(10);tabRow.addView(reorder,reorderParams);count=text(tr("טוען אפליקציות…","Загрузка приложений…"),14);count.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);tabRow.addView(count,new LinearLayout.LayoutParams(0,dp(43),1));root.addView(tabRow);
        FrameLayout panel=new FrameLayout(this);panel.setBackground(surface(0xD0101114,0x44444444));LinearLayout.LayoutParams panelParams=new LinearLayout.LayoutParams(-1,0,1);panelParams.bottomMargin=dp(12);root.addView(panel,panelParams);grid=new RecyclerView(this);grid.setLayoutManager(new GridLayoutManager(this,3));grid.setItemAnimator(null);grid.setClipToPadding(false);grid.setPadding(dp(7),dp(7),dp(7),dp(7));grid.setAdapter(new Rows());panel.addView(grid,new FrameLayout.LayoutParams(-1,-1));
        LinearLayout footer=new LinearLayout(this);for(int i=0;i<3;i++){final int action=i;String name=i==0?tr("↻  איפוס קטגוריה","↻  Сбросить категорию"):i==1?tr("✕  ביטול","✕  Отмена"):tr("✓  שמור שינויים","✓  Сохранить");TextView b=button(name,()->{if(action==0)reset();else if(action==1)finish();else save();},i==2);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(i==1?140:185),dp(44));p.rightMargin=dp(12);footer.addView(b,p);}TextView help=text(tr("אישור: סימון או ביטול  ·  חזרה: יציאה ללא שמירה","ОК: выбрать  ·  Назад: выйти без сохранения"),12);help.setTextColor(0xFFBBBBBB);help.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);footer.addView(help,new LinearLayout.LayoutParams(0,dp(44),1));root.addView(footer);setContentView(root);
        LOADER.execute(()->{PackageManager pm=getPackageManager();Map<String,ResolveInfo> unique=new LinkedHashMap<>();for(String cat:new String[]{android.content.Intent.CATEGORY_LEANBACK_LAUNCHER,android.content.Intent.CATEGORY_LAUNCHER})for(ResolveInfo info:pm.queryIntentActivities(new android.content.Intent(android.content.Intent.ACTION_MAIN).addCategory(cat),0))if(info.activityInfo!=null&&info.activityInfo.exported&&!info.activityInfo.packageName.equals(getPackageName()))unique.putIfAbsent(info.activityInfo.packageName,info);List<App> result=new ArrayList<>();for(ResolveInfo info:unique.values()){try{result.add(new App(info.activityInfo.packageName,info.loadLabel(pm).toString(),info.loadIcon(pm)));}catch(RuntimeException ignored){}}result.sort((a,b)->a.name.compareToIgnoreCase(b.name));runOnUiThread(()->{if(isFinishing()||isDestroyed())return;apps.addAll(result);for(String key:new String[]{"tv","movies","apps"}){Set<String> selection=new HashSet<>();for(App app:apps)if(CategoryDock.visible(this,key,app.pkg))selection.add(app.pkg);draft.put(key,selection);}if(saved!=null)for(String key:new String[]{"tv","movies","apps"}){ArrayList<String> list=saved.getStringArrayList(key);if(list!=null)draft.put(key,new HashSet<>(list));}for(String key:new String[]{"tv","movies","apps"}){ArrayList<String> savedOrder=saved==null?null:saved.getStringArrayList("order_"+key);orderDraft.put(key,savedOrder!=null?savedOrder:CategoryOrder.load(this,key));}
        if(saved!=null&&saved.getStringArrayList("orderDirty")!=null)orderDirty.addAll(saved.getStringArrayList("orderDirty"));
        if(saved!=null&&saved.getStringArrayList("dirty")!=null)dirty.addAll(saved.getStringArrayList("dirty"));arrange();ready=true;updateTabs();grid.getAdapter().notifyDataSetChanged();grid.post(this::focusFirst);});});
    }
    @Override public void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);for(String key:draft.keySet())out.putStringArrayList(key,new ArrayList<>(draft.get(key)));out.putStringArrayList("dirty",new ArrayList<>(dirty));for(String key:orderDraft.keySet())out.putStringArrayList("order_"+key,new ArrayList<>(orderDraft.get(key)));out.putStringArrayList("orderDirty",new ArrayList<>(orderDirty));}
    private void focusFirst(){RecyclerView.ViewHolder h=grid.findViewHolderForAdapterPosition(0);if(h!=null)h.itemView.requestFocus();}
    private void updateTabs(){for(String key:tabs.keySet()){TextView tab=tabs.get(key);tab.setText((key.equals(category)?"✓  ":"")+label(key));tab.setBackground(surface(key.equals(category)?0xFF063C86:0xFF252525,key.equals(category)?0xFF72B2FF:0x66777777));}count.setText(tr("נבחרו ","Выбрано ")+draft.get(category).size()+tr(" מתוך "," из ")+apps.size());}
    private void switchCategory(String key){category=key;focusPackage="";arrange();updateTabs();grid.getAdapter().notifyDataSetChanged();grid.scrollToPosition(0);}
    private void reset(){Set<String> selection=new HashSet<>();for(App app:apps)if(category.equals("apps")||category.equals("tv")&&(app.pkg.equals(CategoryDock.tvPackage(this,"tivimate"))||app.pkg.equals(CategoryDock.tvPackage(this,"mediabox"))))selection.add(app.pkg);draft.put(category,selection);dirty.add(category);orderDraft.put(category,new ArrayList<>());orderDirty.add(category);arrange();grid.getAdapter().notifyDataSetChanged();updateTabs();}
    private void save(){android.content.SharedPreferences.Editor editor=CategoryDock.prefs(this).edit();for(String key:dirty)editor.putStringSet(key.equals("movies")?"movies":key+"_apps",new HashSet<>(draft.get(key)));for(String key:orderDirty)editor.putString("order_"+key,new org.json.JSONArray(orderDraft.get(key)).toString());String old=CategoryDock.prefs(this).getString("tv","");String pkg=CategoryDock.tvPackage(this,old);if(dirty.contains("tv")&&(pkg==null||!draft.get("tv").contains(pkg)))editor.remove("tv");if(editor.commit()){Toast.makeText(this,tr("השינויים נשמרו","Изменения сохранены"),Toast.LENGTH_SHORT).show();finish();}else Toast.makeText(this,tr("השמירה לא הצליחה. נסו שוב.","Не удалось сохранить. Повторите попытку."),Toast.LENGTH_LONG).show();}
    private void arrange(){List<String> order=orderDraft.get(category);if(order==null)return;Map<String,Integer> rank=new HashMap<>();for(int i=0;i<order.size();i++)rank.put(order.get(i),i);apps.sort((a,b)->{int byOrder=CategoryOrder.compare(rank,a.pkg,b.pkg);return byOrder!=0?byOrder:a.name.compareToIgnoreCase(b.name);});}
    private void openOrder(){ArrayList<String> chosen=new ArrayList<>();List<App> sorted=new ArrayList<>(apps);List<String> order=orderDraft.get(category);Map<String,Integer> ranks=new HashMap<>();for(int i=0;i<order.size();i++)ranks.put(order.get(i),i);sorted.sort((a,b)->{int result=CategoryOrder.compare(ranks,a.pkg,b.pkg);return result!=0?result:a.name.compareToIgnoreCase(b.name);});for(App app:sorted)if(draft.get(category).contains(app.pkg))chosen.add(app.pkg);if(chosen.isEmpty()){Toast.makeText(this,tr("בחרו אפליקציות להצגה לפני שינוי הסדר","Сначала выберите приложения"),Toast.LENGTH_LONG).show();return;}startActivityForResult(new android.content.Intent(this,CategoryOrderActivity.class).putExtra("category",category).putStringArrayListExtra("packages",chosen),701);}
    @Override protected void onActivityResult(int request,int result,android.content.Intent data){super.onActivityResult(request,result,data);if(request==701&&result==RESULT_OK&&data!=null){String key=data.getStringExtra("category");ArrayList<String> order=data.getStringArrayListExtra("order");if(key!=null&&order!=null){orderDraft.put(key,new ArrayList<>(order));orderDirty.add(key);arrange();grid.getAdapter().notifyDataSetChanged();updateTabs();}}}
    private static final class App{final String pkg,name;final Drawable icon;App(String p,String n,Drawable d){pkg=p;name=n;icon=d;}}
    private final class Rows extends RecyclerView.Adapter<Row>{
        @NonNull @Override public Row onCreateViewHolder(@NonNull ViewGroup parent,int type){FrameLayout cell=new FrameLayout(CategorySettingsActivity.this);RecyclerView.LayoutParams lp=new RecyclerView.LayoutParams(-1,dp(60));lp.setMargins(dp(3),dp(3),dp(3),dp(3));cell.setLayoutParams(lp);cell.setFocusable(true);cell.setClickable(true);cell.setClipChildren(false);LinearLayout body=new LinearLayout(CategorySettingsActivity.this);body.setPadding(dp(12),dp(5),dp(12),dp(5));body.setGravity(Gravity.CENTER_VERTICAL);cell.addView(body,new FrameLayout.LayoutParams(-1,-1));ImageView icon=new ImageView(CategorySettingsActivity.this);icon.setScaleType(ImageView.ScaleType.FIT_CENTER);body.addView(icon,new LinearLayout.LayoutParams(dp(43),dp(43)));TextView name=text("",14);name.setSingleLine(true);name.setEllipsize(android.text.TextUtils.TruncateAt.END);LinearLayout.LayoutParams np=new LinearLayout.LayoutParams(0,-2,1);np.leftMargin=dp(10);body.addView(name,np);TextView check=text("",18);check.setTypeface(Typeface.DEFAULT,Typeface.BOLD);check.setGravity(Gravity.CENTER);body.addView(check,new LinearLayout.LayoutParams(dp(25),dp(25)));GlassView ring=new GlassView(CategorySettingsActivity.this,null);ring.setStyle(Config.GLASS_HALO);ring.setRadius(dp(12));ring.setAlpha(0);cell.addView(ring,new FrameLayout.LayoutParams(-1,-1));return new Row(cell,icon,name,check,ring);}
        @Override public void onBindViewHolder(@NonNull Row h,int position){App app=apps.get(position);boolean selected=draft.get(category).contains(app.pkg);h.icon.setImageDrawable(app.icon);h.name.setText(app.name);h.check.setText(selected?"✓":"");h.check.setBackground(surface(selected?0xFF0068ED:0xFF17191D,selected?0xFF38A5FF:0xFF777777));h.itemView.setBackground(surface(selected?0xFF071B2E:0xFF16171A,0xFF34363A));h.itemView.setContentDescription(app.name+" · "+tr(selected?"מוצג":"מוסתר",selected?"показывать":"скрыть"));h.ring.setAlpha(h.itemView.hasFocus()?1:0);h.itemView.setOnClickListener(v->{Set<String> set=draft.get(category);if(!set.add(app.pkg))set.remove(app.pkg);dirty.add(category);notifyItemChanged(h.getBindingAdapterPosition());updateTabs();});h.itemView.setOnFocusChangeListener((v,has)->{h.ring.animate().alpha(has?1:0).setDuration(100).start();h.name.setTypeface(Typeface.DEFAULT,has?Typeface.BOLD:Typeface.NORMAL);if(has)focusPackage=app.pkg;});}
        @Override public int getItemCount(){return apps.size();}
    }
    private static final class Row extends RecyclerView.ViewHolder{final ImageView icon;final TextView name,check;final GlassView ring;Row(View v,ImageView i,TextView n,TextView c,GlassView r){super(v);icon=i;name=n;check=c;ring=r;}}
}
